function eb.weatherStrength(sm)
local tm=eb.fx(sm)
local um=tm.dmg/tm.cd/tm.hp/tm.speed*(1+(tm.range-1)/2)
for vm,wm in pairs(tm.kinds)do
um=um*(1+Q.rogueShare(vm)*wm)
end
if tm.ice>0 then
local xm=Q.rogueShare(noc[1595])
um=um*(xm+(1-xm)/(1-tm.ice+tm.ice/W.modFactor(noc[1625])))
end
if tm.fly>0 then
um=um*(1-tm.fly*0.5)
end
if tm.noCC then
um=um*0.95
end
if tm.shroud then
um=um*0.9
end
return um
end
