function eb.skinTick()
if not(I.skinSmart or I.starOpen)or not(J.live.event and eb.is(J.live.event.level))then
return
end
if(j.req.back.skins or 0)>M.now()then
return
end
local qo=H.session()
local function ro(so,uo,vo)
local wo=j.gameSaid(uo)
P.pickNote.skins=string.format(noc[1679],so,tostring(wo or vo or noc[1680]))
j.log(1,noc[1613],P.pickNote.skins)
j.backoff(noc[1681],1800)
end
local xo=eb.skinPlan()
if I.skinSmart then
local yo=xo.wear[1]
if yo and(j.req.back.skinWear or 0)<=M.now()then
local zo=db.slotOf(yo.unit)
if zo then
J.str.reequip={uuid=yo.unit,slot=zo}
j.saveNow()
j.request(noc[1682],noc[1683],yo.unit)
local Ao=M.now()
while M.now()-Ao<4 and db.slotOf(yo.unit)do
task.wait(0.25)
end
end
local Bo=M.now()
local Co,Do=j.request(noc[1684],noc[1685],yo.uuid,{unit_uuid=yo.unit})
local function Eo()
local Fo=qo.collection:get_unit_by_uuid(yo.unit)
return Fo and Fo.skin~=nil
end
while M.now()-Bo<5 and not Eo()do
task.wait(0.25)
end
if zo then
db.reequip()
end
if Eo()then
j.log(1,noc[1613],string.format(noc[1686],yo.name,yo.unitName))
P.pickNote.skins=nil
xo=eb.skinPlan()
else
local Go=j.gameSaid(Bo)
P.pickNote.skins=string.format(noc[1687],yo.name,tostring(Go or Do or noc[1680]))
j.log(1,noc[1613],P.pickNote.skins)
j.backoff(noc[1684],1800)
end
end
if#xo.sell>0 then
local Ho,Io={},0
for Jo=1,math.min(50,#xo.sell)do
table.insert(Ho,xo.sell[Jo].uuid)
Io=Io+xo.sell[Jo].pearls
end
local Ko=tonumber(H.cur(noc[1652]))or 0
local Lo=M.now()
local Mo,No=j.request(noc[1688],noc[1689],Ho)
while M.now()-Lo<5 and(tonumber(H.cur(noc[1652]))or 0)<=Ko do
task.wait(0.25)
end
local Oo=(tonumber(H.cur(noc[1652]))or 0)-Ko
if Oo<=0 then
return ro(noc[1690],Lo,No)
end
R.add(string.format(noc[1691],#Ho),#Ho,noc[1681],string.format(noc[1692],M.fmt(Oo)))
P.pickNote.skins=nil
end
end
if I.starOpen then
local Po=qo.inventory
local function Qo()
local Ro,So=pcall(Po.get_number_of_owned_item,Po,eb.STAR)
return Ro and tonumber(So)or 0
end
local To=M.now()
for Uo=1,8 do
if M.now()-To>15 or not j.alive or j.where~=noc[1484]then
break
end
local Vo=Qo()
local Wo=eb.starPlan(eb.skinPlan())
local Xo=M.now()
if Vo>0 then
local Yo,Zo=j.request(noc[1693],noc[1694],eb.STAR,{use10=Vo>=10,use_all=false})
while M.now()-Xo<6 and Qo()>=Vo do
task.wait(0.25)
end
if Qo()>=Vo then
return ro(noc[1695],Xo,Zo)
end
j.log(1,noc[1613],string.format(noc[1696],Vo-Qo(),(tonumber(((H.prof().capsule_pity_data or{})[eb.STAR]or{}).total_opens)or 0)))
P.pickNote.skins=nil
