for Rw,Sw in pairs(Ow.evolve and Ow.evolve.normal and Ow.evolve.normal.item_requirement or{})do
local Tw=H.SaleEvent[Sw.item_id]
if Tw and type(Tw.resource_cost)==noc[1417]and Tw.resource_cost.id==noc[1813]then
