function bb.bestInfinite()
local dQ,eQ
for fQ,gQ in ipairs(O.lastScored or{})do
if gQ.kind==noc[1436]and bb.eligible(gQ)then
local hQ,iQ=J.train.real[gQ.key],gQ.rec or O.rec(gQ.key)
local jQ=(tonumber(iQ.timed)or 0)>0 and iQ.sec/iQ.timed/60 or 0
local kQ=(hQ and hQ.n>0 and jQ>0)and(hQ.sum/hQ.n)/jQ or 0
if kQ<=0 then
kQ=U.hiveTrainRate(gQ.key)or 0
end
if kQ>(eQ or 0)then
dQ,eQ=gQ,kQ
end
end
end
return dQ
end
function bb.ratio()
local lQ=J.train.cal
if not(lQ and(lQ.n or 0)>0 and(lQ.sim or 0)>0)then
return 1
end
return M.clamp(lQ.real/lQ.sim,0.05,2)
end
function bb.perRun(mQ,nQ)
local oQ=J.train.real[mQ]
if oQ and oQ.n>0 then
return oQ.sum/oQ.n,true
end
local pQ=U.hiveTrain(mQ,nQ)
if pQ then
return pQ,true
end
local qQ,rQ=0,0
local sQ=O.isInf(mQ)
for tQ,uQ in pairs(J.train.real)do
if O.isInf(tQ)==sQ then
qQ,rQ=qQ+uQ.sum,rQ+uQ.n
end
end
if rQ>0 then
return qQ/rQ,true
end
local vQ=J.trainSim[mQ]
return vQ and vQ.tk and vQ.tk*bb.ratio()or nil,false
end
