local vJb,wJb=Q.bestSpot(sJb,uJb or(Q.random and N.idol(sJb.id)),(Q.trainee~=nil and sJb.uuid==Q.trainee)or N.ENTRY[sJb.id]==true)
if not vJb then
Q.noSpot[sJb.uuid]=(Q.noSpot[sJb.uuid]or 0)+1
j.status(noc[2778],noc[2788]..N.name(sJb.id))
return false
end
local xJb=Q.money()
local yJb,zJb=j.request(noc[2789],noc[2790],sJb.uuid,H.Util.CFramePLV(vJb,Q.lookAt(vJb)))
if yJb and zJb then
Q.spent=Q.spent+(sJb.data.cost or 0)
table.insert(Q.actions,string.format(noc[2791],N.name(sJb.id)))
j.log(1,noc[2783],string.format(noc[2792],N.name(sJb.id),Q.spotKey(vJb),wJb,tJb))
Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=sJb.id,x=math.floor(vJb.X),z=math.floor(vJb.Z),cover=math.floor((wJb or 0)+0.5),why=tostring(tJb):sub(1,90)})
j.status(noc[2778],string.format(noc[2793],N.name(sJb.id),tJb))
Q.placedAt=Q.placedAt or{}
Q.placedAt[sJb.uuid]=(Q.placedAt[sJb.uuid]or 0)+1
return true
end
if xJb>=(sJb.data.cost or 0)and Q.random then
Q.placeFail=Q.placeFail or{}
Q.placeFail[sJb.uuid]=(Q.placeFail[sJb.uuid]or 0)+1
if Q.placeFail[sJb.uuid]>=2 then
Q.noSpot[sJb.uuid]=3
j.log(1,noc[2783],string.format(noc[2794],N.name(sJb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if yJb and xJb>=(sJb.data.cost or 0)and not Q.random then
local AJb=Q.spotKey(vJb)
Q.refused[AJb]=true
local BJb=Q.mapKey()
J.blocked[BJb]=J.blocked[BJb]or{}
if not Q.refusedRun[AJb]then
J.blocked[BJb][AJb]=(tonumber(J.blocked[BJb][AJb])or 0)+1
Q.refusedRun[AJb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[sJb.uuid]=(Q.unitRefusals[sJb.uuid]or 0)+1
if Q.unitRefusals[sJb.uuid]>=3 then
local CJb=math.max(1,Q.count(sJb.uuid))
if J.caps[sJb.uuid]~=CJb then
J.caps[sJb.uuid]=CJb
j.log(1,noc[2783],string.format(noc[2795],N.name(sJb.id),CJb))
end
end
j.log(2,noc[2783],noc[2796]..AJb..noc[1833]..N.name(sJb.id))
j.saveSoon()
end
return false
end
function Q.count(DJb)
local EJb=0
for FJb,GJb in ipairs({workspace._UNITS,workspace:FindFirstChild(noc[2797])})do
if GJb then
for HJb,IJb in ipairs(GJb:GetChildren())do
local JJb=IJb:FindFirstChild(noc[1476])
if JJb and JJb:FindFirstChild(noc[2786])and JJb.player.Value==G and JJb.uuid.Value==DJb then
EJb=EJb+1
end
end
end
end
return EJb
end
function Q.measure()
local KJb,LJb=Q.calRun,Q.info
if not(KJb and LJb)then
return
end
pcall(Q.sampleHelpers)
local MJb=M.now()
local NJb=Q.wave()
local OJb=Q.money()
if not KJb.start and OJb>0 and#Q.mine==0 then
KJb.start=OJb
end
if NJb~=KJb.lastW then
if Q.trialId and NJb>0 then
Q.trialTrace=Q.trialTrace or{}
local PJb,QJb,RJb,SJb=0,{},0,0
for TJb,UJb in ipairs(Q.mine)do
local VJb=UJb._stats
if VJb.id.Value==Q.trialId then
PJb=PJb+1
table.insert(QJb,tostring(VJb.upgrade.Value))
elseif not N.isFarm(VJb.id.Value)then
SJb=SJb+1
end
end
pcall(Q.sampleHelpers,true)
for WJb,XJb in pairs(Q.ownDealt)do
if XJb.id==Q.trialId then
RJb=RJb+XJb.v
end
end
local YJb=0
for ZJb,_Jb in pairs(Q.helperDealt)do
if _Jb.owner==Q.trialId then
YJb=YJb+_Jb.v
end
end
table.insert(Q.trialTrace,string.format(noc[2798],NJb,MJb-(Q.startT or MJb),OJb,table.concat(QJb,noc[1895]),SJb,RJb+YJb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[NJb-1]or 0,Q.teamDps or 0))
end
if KJb.lastW and KJb.lastW>0 and KJb.lastWT then
table.insert(KJb.waveSec,MJb-KJb.lastWT)
end
if KJb.paidT and NJb>0 and MJb-KJb.paidT<15 then
table.insert(KJb.skip,MJb-KJb.paidT)
end
KJb.paidT=nil
if NJb>0 then
KJb.alive[tostring(NJb)]=Q.hpAliveRaw or 0
end
KJb.lastW,KJb.lastWT=NJb,MJb
end
local aKb=workspace:FindFirstChild(noc[2799])
if aKb and NJb>0 then
KJb.timer[tostring(NJb)]=math.max(KJb.timer[tostring(NJb)]or 0,tonumber(aKb.Value)or 0)
end
local bKb=OJb-(Q.lastMoneyR or OJb)
Q.lastMoneyR=OJb
Q.incomeLog=Q.incomeLog or{}
if bKb>0 then
table.insert(Q.incomeLog,{t=MJb,y=bKb})
end
while Q.incomeLog[1]and MJb-Q.incomeLog[1].t>30 do
table.remove(Q.incomeLog,1)
end
local cKb=0
for dKb,eKb in ipairs(Q.incomeLog)do
cKb=cKb+eKb.y
end
local fKb=math.min(30,MJb-(Q.startT or MJb))
Q.incomeRate=fKb>=8 and cKb/fKb or nil
for gKb,hKb in ipairs(Q.enemies)do
local iKb=hKb.m
local jKb=Q.track[iKb]
if not jKb then
local kKb=iKb._stats
local lKb=iKb:FindFirstChildOfClass(noc[2725])
local mKb=LJb.cfgById[kKb.id.Value]
local nKb=mKb and W.baseStats(LJb,mKb)
if lKb and nKb and NJb>0 then
local oKb=nKb*LJb.hpRaw*W.waveScale(LJb,NJb,LJb.list[NJb])
if oKb>0 and lKb.MaxHealth>0 then
table.insert(KJb.hp,lKb.MaxHealth/oKb)
end
end
Q.track[iKb]={t=MJb,p=hKb.prog,sp=(kKb:FindFirstChild(noc[2800])and tonumber(kKb.speed.Value))or 1}
if NJb>0 then
KJb.spawn[tostring(NJb)]=(KJb.spawn[tostring(NJb)]or 0)+1
KJb.spawnLast[tostring(NJb)]=MJb-(KJb.lastWT or MJb)
end
elseif not jKb.done and MJb-jKb.t>=15 then
jKb.done=true
local pKb=(hKb.prog-jKb.p)/(MJb-jKb.t)/math.max(0.1,jKb.sp)
if pKb>0.001 and hKb.prog<0.95 then
table.insert(KJb.walk,pKb)
end
end
end
local qKb=0
for rKb,sKb in ipairs(Q.mine)do
local tKb=sKb._stats:FindFirstChild(noc[2801])
if tKb then
qKb=qKb+tKb.Value
end
end
KJb.potSum=KJb.potSum or 0
if KJb.lastDealtT then
local uKb=MJb-KJb.lastDealtT
local vKb=0
for wKb,xKb in ipairs(Q.mine)do
local yKb=xKb._stats
local zKb=yKb.id.Value
if not N.isFarm(zKb)and yKb:FindFirstChild(noc[2802])and yKb.target.Value~=nil then
local AKb,BKb=pcall(Q.liveDps,xKb,zKb)
if AKb and BKb then
vKb=vKb+BKb*uKb
end
end
end
KJb.potWin=(KJb.potWin or 0)+vKb
if MJb-(KJb.winT or MJb)>=5 then
local CKb=qKb-(KJb.winDealt or qKb)
if KJb.potWin>0 and CKb>=0 then
KJb.dealtSum=(KJb.dealtSum or 0)+CKb
KJb.potSum=KJb.potSum+KJb.potWin
end
KJb.winT,KJb.winDealt,KJb.potWin=MJb,qKb,0
end
end
if not KJb.winT then
KJb.winT,KJb.winDealt=MJb,qKb
end
KJb.lastDealtT=MJb
if NJb~=KJb.dpsW and NJb>0 then
KJb.dpsAt[tostring(NJb)]=Q.teamDps or 0
KJb.dpsW=NJb
end
local DKb=math.min(1,MJb-(KJb.densT or MJb))
KJb.densT=MJb
for EKb,FKb in ipairs(Q.enemies)do
local GKb=math.min(W.BINS,math.floor(FKb.prog*W.BINS)+1)
KJb.dens[GKb]=(KJb.dens[GKb]or 0)+DKb
end
local HKb=workspace._BASES.player:FindFirstChild(noc[2803])
local IKb=HKb and HKb:FindFirstChild(noc[2804])
local JKb=IKb and IKb:FindFirstChildOfClass(noc[2725])
if JKb then
KJb.baseHp=math.max(KJb.baseHp or 0,JKb.MaxHealth)
local KKb=0
for LKb,MKb in ipairs(Q.enemies)do
if MKb.prog>=0.97 then
local NKb=MKb.m:FindFirstChildOfClass(noc[2725])
KKb=KKb+(NKb and NKb.MaxHealth or MKb.hp)
end
end
if KJb.lastBase and JKb.Health<KJb.lastBase and KKb>0 and KJb.lastBaseT then
table.insert(KJb.baseRel,(KJb.lastBase-JKb.Health)/math.max(0.1,MJb-KJb.lastBaseT)/KKb)
end
KJb.lastBase,KJb.lastBaseT=JKb.Health,MJb
end
end
function Q.recordMap()
local OKb=Q.mapKey()
local PKb=J.maps[OKb]
if PKb and PKb.v==1 and PKb.laneV and(PKb.densN or 0)==(PKb.binsDensN or 0)then
return
end
if PKb and PKb.v==1 and PKb.laneV and(PKb.densN or 0)>5 and(PKb.binsDensN or 0)>=5 then
return
end
local QKb={override_hitbox_radius=1.75}
local RKb={hill_unit=true,override_hitbox_radius=1.75}
local SKb,TKb={},false
for UKb,VKb in ipairs(Q.cands)do
local WKb=Q.valid(VKb,QKb)
if WKb then
table.insert(SKb,WKb)
end
if not TKb and Q.valid(VKb,RKb)then
TKb=true
end
if UKb%30==0 then
task.wait()
end
end
local XKb,YKb={},{}
local ZKb=W.laneList(Q.samples)
for _Kb=5,60,5 do
local aLb,bLb
for cLb,dLb in ipairs(SKb)do
local eLb=Q.cover(dLb,_Kb,true)
if not bLb or eLb>bLb then
aLb,bLb=dLb,eLb
end
end
if aLb then
local fLb,gLb={},{}
for hLb=1,W.BINS do
fLb[hLb]=noc[2565]
end
for iLb,jLb in ipairs(ZKb or{})do
gLb[jLb]={}
for kLb=1,W.BINS do
gLb[jLb][kLb]=noc[2565]
end
end
local lLb=M.flat(aLb)
for mLb,nLb in ipairs(Q.samples)do
if(M.flat(nLb.pos)-lLb).Magnitude<=_Kb then
local oLb=math.min(W.BINS,math.floor(nLb.prog*W.BINS)+1)
fLb[oLb]=noc[1554]
if gLb[tostring(nLb.lane)]then
gLb[tostring(nLb.lane)][oLb]=noc[1554]
end
end
end
XKb[tostring(_Kb)]=table.concat(fLb)
if ZKb then
YKb[tostring(_Kb)]={}
for pLb,qLb in pairs(gLb)do
YKb[tostring(_Kb)][pLb]=table.concat(qLb)
end
end
end
task.wait()
end
local rLb=J.maps[OKb]or{}
J.maps[OKb]={v=1,laneV=1,bins=XKb,binsL=ZKb and YKb or nil,lanes=ZKb,hill=TKb,spots= #SKb,dens=rLb.dens,densN=rLb.densN,binsDensN=rLb.densN or 0,lay=rLb.lay,walk=rLb.walk,walkN=rLb.walkN}
W._masks={}
j.log(1,noc[2512],string.format(noc[2805],OKb,#SKb,TKb and noc[2806]or noc[2807]))
j.saveSoon()
end
Q.helperDealt,Q.helperAt,Q.ownDealt={},0,{}
function Q.sampleHelpers(sLb)
if not sLb and M.now()-Q.helperAt<3 then
return
end
Q.helperAt=M.now()
local tLb=workspace:FindFirstChild(noc[2716])
local uLb={}
