local xLb=wLb:FindFirstChild(noc[1476])
local yLb=xLb and xLb:FindFirstChild(noc[2801])
if yLb and xLb:FindFirstChild(noc[2456])then
local zLb=Q.ownDealt[wLb]or{id=xLb.id.Value,v=0,lvl=0}
zLb.v=math.max(zLb.v,yLb.Value)
zLb.lvl=math.max(zLb.lvl,xLb:FindFirstChild(noc[1503])and tonumber(xLb.upgrade.Value)or 0)
