local DLb=CLb and CLb:FindFirstChild(noc[2722])
local ELb=CLb and CLb:FindFirstChild(noc[2801])
if DLb and ELb and DLb.Value~=nil and uLb[DLb.Value]then
local FLb=DLb.Value:FindFirstChild(noc[1476])
local GLb=Q.helperDealt[BLb]or{id=CLb.id.Value,owner=FLb and FLb:FindFirstChild(noc[2456])and FLb.id.Value or nil,v=0}
GLb.v=math.max(GLb.v,ELb.Value)
Q.helperDealt[BLb]=GLb
