function Q.damageShares()
pcall(Q.sampleHelpers,true)
local TLb,ULb={},0
local function VLb(WLb,XLb)
TLb[WLb]=(TLb[WLb]or 0)+XLb
ULb=ULb+XLb
end
for YLb,ZLb in pairs(Q.ownDealt)do
if not N.isFarm(ZLb.id)then
VLb(ZLb.id,ZLb.v)
end
end
local _Lb=0
for aMb,bMb in pairs(Q.helperDealt)do
VLb(bMb.owner or noc[1751],bMb.v)
_Lb=_Lb+1
end
if ULb<=0 then
return nil
end
for cMb,dMb in pairs(TLb)do
TLb[cMb]=dMb/ULb
end
return TLb,ULb,_Lb
end
function Q.summonSplit()
local eMb,fMb={},{}
for gMb,hMb in pairs(Q.ownDealt)do
eMb[hMb.id]=(eMb[hMb.id]or 0)+(tonumber(hMb.v)or 0)
end
for iMb,jMb in pairs(Q.helperDealt)do
if jMb.owner then
fMb[jMb.owner]=(fMb[jMb.owner]or 0)+(tonumber(jMb.v)or 0)
end
end
local kMb={}
for lMb,mMb in pairs(fMb)do
local nMb=mMb+(eMb[lMb]or 0)
if nMb>0 then
kMb[lMb]={share=mMb/nMb,total=nMb}
end
end
return kMb
end
function Q.damageLine()
