return string.format(noc[2808],M.fmt(pMb),table.concat(wMb,noc[1608]),qMb>0 and string.format(noc[2809],qMb)or noc[346],#BMb>0 and(noc[2810]..table.concat(BMb,noc[1512]))or noc[346])
